// app.js
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();

app.use(cors());
app.use(express.json());

// In-memory store
let todos = [];

/**
 * Validation Helper
 */
const validateTodo = (data) => {
  const { title } = data;
  if (!title || typeof title !== 'string' || title.trim().length < 1 || title.trim().length > 100) {
    throw new Error('Title is required and must be a string between 1 and 100 characters');
  }
};

/**
 * GET /todos
 * Query params: completed=true|false
 */
app.get('/todos', (req, res) => {
  const { completed } = req.query;
  let filteredTodos = todos;

  if (completed !== undefined) {
    const isCompleted = completed === 'true';
    filteredTodos = todos.filter(t => String(t.completed) === isCompleted);
  }

  res.json(filteredTodos);
});

/**
 * GET /todos/:id
 */
app.get('/todos/:id', (req, res) => {
  const todo = todos.find(t => t.id === req.params.id);
  if (!todo) return res.status(404).json({ error: 'Todo not found' });
  res.json(todo);
});

/**
 * POST /todos
 */
app.post('/todos', (req, res) => {
  try {
    const { title, completed } = req.body;
    validateTodo(req.body);

    const newTodo = {
      id: uuidv4(),
      title: title.trim(),
      completed: !!completed, // ensure boolean
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    todos.push(newTodo);
    res.status(201).json(newTodo);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

/**
 * PUT /todos/:id
 */
app.put('/todos/:id', (req, res) => {
  const index = todos.findIndex(t => t.id === req.params.id);
  if (index === -1) return res.status(404).json({ error: 'Todo not found' });

  try {
    const { title, completed } = req.body;

    // Validation logic for updates (only validate if field is present)
    if (title !== undefined) {
      if (typeof title !== 'string' || title.trim().length < 1 || title.trim().length > 100) {
        return res.status(400).json({ error: 'Title must be a string between 1 and 100 characters' });
      }
    }

    const updatedTodo = {
      ...todos[index],
      title: title !== undefined ? title.trim() : todos[index].title,
      completed: completed !== undefined ? !!completed : todos[index].completed,
      updatedAt: new Date().toISOString()
    };

    todos[index] = updatedTodo;
    res.json(updatedTodo);
  } catch (err) {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

/**
